  /**
   * Encodes a latitude/longitude pair into sortable bytes using the same quantization as {@link
   * #encodeLatitude(double)} and {@link #encodeLongitude(double)}.
   */
  public static void encodeLatLon(double latitude, double longitude, byte[] dest, int offset) {
    newSession().writeQuantizedPoint(latitude, longitude, dest, offset, false);
  }

  /**
   * Encodes a latitude/longitude pair into sortable bytes, rounding toward +90/+180.
   */
  public static void encodeLatLonCeil(double latitude, double longitude, byte[] dest, int offset) {
    newSession().writeQuantizedPoint(latitude, longitude, dest, offset, true);
  }

  /**
   * Packs a latitude/longitude pair into a 64-bit doc values ordinate (lat in the high 32 bits).
   */
  public static long packLatLon(double latitude, double longitude) {
    return newSession().packQuantizedPoint(latitude, longitude);
  }

  /**
   * Quantizes a bounding box to inclusive encoded ranges using ceil on the lower edges and floor on
   * the upper edges, matching indexed point range queries.
   */
  public static int[] encodeBoxRange(
      double minLatitude, double maxLatitude, double minLongitude, double maxLongitude) {
    return newSession().quantizeBoxRange(minLatitude, maxLatitude, minLongitude, maxLongitude);
  }

  private void writeQuantizedPoint(
      double lat, double lon, byte[] dest, int offset, boolean ceil) {
    int encodedLat = ceil ? encodeLatitudeCeil(lat) : encodeLatitude(lat);
    int encodedLon = ceil ? encodeLongitudeCeil(lon) : encodeLongitude(lon);
    applyPointEncodingPipeline(encodedLat, encodedLon);
    NumericUtils.intToSortableBytes(sessionEncodedLatitude, dest, offset);
    NumericUtils.intToSortableBytes(sessionEncodedLongitude, dest, offset + Integer.BYTES);
  }

  private long packQuantizedPoint(double lat, double lon) {
    int encodedLat = encodeLatitude(lat);
    int encodedLon = encodeLongitude(lon);
    applyPointEncodingPipeline(encodedLat, encodedLon);
    return sessionPackedOrdinate;
  }

  private int[] quantizeBoxRange(
      double minLatitude, double maxLatitude, double minLongitude, double maxLongitude) {
    int minLat = encodeLatitudeCeil(minLatitude);
    int maxLat = encodeLatitude(maxLatitude);
    int minLon = encodeLongitudeCeil(minLongitude);
    int maxLon = encodeLongitude(maxLongitude);
    applyPointEncodingPipeline(minLat, minLon);
    applyGridEncodingPipeline(minLat, maxLat, minLon, maxLon, minLongitude > maxLongitude);
    return new int[] {minLat, maxLat, minLon, maxLon};
  }

