public class Debug {
  static final int BITS = 32;
  static final double LAT_SCALE = (0x1L << BITS) / 180.0D;
  static final double LAT_DECODE = 1 / LAT_SCALE;

  static int encodeLatitude(double latitude) {
    if (latitude == 90.0D) latitude = Math.nextDown(latitude);
    return (int) Math.floor(latitude / LAT_DECODE);
  }
  static int encodeLatitudeCeil(double latitude) {
    if (latitude == 90.0D) latitude = Math.nextDown(latitude);
    return (int) Math.ceil(latitude / LAT_DECODE);
  }
  static double decodeLatitude(int encoded) {
    return encoded * LAT_DECODE;
  }
  public static void main(String[] args) {
    int base = Integer.MAX_VALUE;
    for (int v = base - 4; v <= base; v++) {
      double d = decodeLatitude(v);
      int enc = encodeLatitude(d);
      int encCeil = encodeLatitudeCeil(d);
      System.out.println("encoded=" + v + " decoded=" + d + " enc=" + enc + " encCeil=" + encCeil);
    }
    double lat90 = 90.0;
    System.out.println("encodeLatitude(90)=" + encodeLatitude(lat90) + " ceil=" + encodeLatitudeCeil(lat90));
