import org.apache.lucene.geo.*;
import org.apache.lucene.index.PointValues.Relation;

public class Debug2 {
  public static void main(String[] args) {
    int base = Integer.MAX_VALUE;
    double minLat = GeoEncodingUtils.decodeLatitude(base - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(base);
    double minLon = GeoEncodingUtils.decodeLongitude(base - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(base);
    Polygon poly = new Polygon(
        new double[] {minLat, minLat, maxLat, maxLat, minLat},
        new double[] {minLon, maxLon, maxLon, minLon, minLon});
    Component2D tree = LatLonGeometry.create(poly);
    System.out.println("bbox: minLat=" + tree.getMinY() + " maxLat=" + tree.getMaxY()
        + " minLon=" + tree.getMinX() + " maxLon=" + tree.getMaxX());

    int minLatE = GeoEncodingUtils.encodeLatitudeCeil(tree.getMinY());
    int maxLatE = GeoEncodingUtils.encodeLatitude(tree.getMaxY());
    int minLonE = GeoEncodingUtils.encodeLongitudeCeil(tree.getMinX());
    int maxLonE = GeoEncodingUtils.encodeLongitude(tree.getMaxX());
    System.out.println("enc: minLat=" + minLatE + " maxLat=" + maxLatE + " minLon=" + minLonE + " maxLon=" + maxLonE);

    long minLat2 = (long) minLatE - Integer.MIN_VALUE;
    long maxLat2 = (long) maxLatE - Integer.MIN_VALUE;
    int latShift = shift(minLat2, maxLat2);
    int latBase = (int) (minLat2 >>> latShift);
    int maxLatDelta = (int) (maxLat2 >>> latShift) - latBase + 1;
    long minLon2 = (long) minLonE - Integer.MIN_VALUE;
    long maxLon2 = (long) maxLonE - Integer.MIN_VALUE;
    int lonShift = shift(minLon2, maxLon2);
    int lonBase = (int) (minLon2 >>> lonShift);
    int maxLonDelta = (int) (maxLon2 >>> lonShift) - lonBase + 1;
    System.out.println("grid: latShift=" + latShift + " latBase=" + latBase + " latDelta=" + maxLatDelta
        + " lonShift=" + lonShift + " lonBase=" + lonBase + " lonDelta=" + maxLonDelta);

    for (int i = 0; i < maxLatDelta; ++i) {
      for (int j = 0; j < maxLonDelta; ++j) {
        int boxMinLat = ((latBase + i) << latShift) + Integer.MIN_VALUE;
        int boxMinLon = ((lonBase + j) << lonShift) + Integer.MIN_VALUE;
        int boxMaxLat = boxMinLat + (1 << latShift) - 1;
        int boxMaxLon = boxMinLon + (1 << lonShift) - 1;
        Rectangle r = new Rectangle(GeoEncodingUtils.decodeLatitude(boxMinLat), GeoEncodingUtils.decodeLatitude(boxMaxLat),
            GeoEncodingUtils.decodeLongitude(boxMinLon), GeoEncodingUtils.decodeLongitude(boxMaxLon));
        Relation rel = tree.relate(r.minLon, r.maxLon, r.minLat, r.maxLat);
        System.out.println("box[" + i + "][" + j + "] lat=[" + boxMinLat + "," + boxMaxLat + "] lon=[" + boxMinLon + "," + boxMaxLon + "] rel=" + rel);
      }
    }

    double pLat = GeoEncodingUtils.decodeLatitude(base - 2);
    double pLon = GeoEncodingUtils.decodeLongitude(base - 2);
    System.out.println("tree.contains(point)=" + tree.contains(pLon, pLat));
    System.out.println("point lat=" + pLat + " lon=" + pLon);
  }
  static int shift(long a, long b) {
    for (int s = 1; ; ++s) {
      long d = (b >>> s) - (a >>> s);
      if (d >= 0 && d < 64) return s;
    }
  }
}
